package com.witchersbestiary.test;
import com.witchersbestiary.fist.*;
import com.witchersbestiary.economy.*;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;
import net.minecraft.block.Blocks;
import net.minecraft.entity.attribute.EntityAttributes;
import net.minecraft.item.*;
import net.minecraft.recipe.*;import net.minecraft.recipe.input.CraftingRecipeInput;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.test.*;
import net.minecraft.util.math.*;
import java.util.*;
public final class DuelTests implements FabricGameTest {
 private static java.util.UUID protectedPlayer;static {DuelPermissions.ALLOW.register((a,b)->!a.getUuid().equals(protectedPlayer));}
 private static final String ARENA="witchersbestiary:village_board_arena";
 private BlockPos field(TestContext c){c.getWorld().getServer().setPvpEnabled(true);for(int x=0;x<48;x++)for(int z=0;z<48;z++){c.setBlockState(new BlockPos(x,1,z),Blocks.STONE);for(int y=2;y<10;y++)c.setBlockState(new BlockPos(x,y,z),Blocks.AIR);}var pos=c.getAbsolutePos(new BlockPos(12,2,24));c.getWorld().setBlockState(pos,DuelStone.BLOCK.getDefaultState());return pos;}
 private ServerPlayerEntity player(TestContext c,BlockPos stone,int offset){var p=c.createMockCreativeServerPlayerInWorld();p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);p.setInvulnerable(false);p.getInventory().clear();p.getInventory().setStack(8,new ItemStack(com.witchersbestiary.economy.Currency.WALLET));p.getInventory().getStack(8).set(WalletComponents.BALANCE,47L);p.getInventory().setStack(7,new ItemStack(Items.DIAMOND,3));p.refreshPositionAndAngles(stone.getX()+.5,stone.getY(),stone.getZ()+offset,0,0);p.setHealth(2);p.getHungerManager().setFoodLevel(10);p.getHungerManager().setSaturationLevel(0);return p;}
 private DuelSessions.Session confirm(TestContext c,BlockPos stone,ServerPlayerEntity a,ServerPlayerEntity b){c.assertTrue(DuelSessions.interact(a,stone),"A waits");var d=DuelSessions.get(a);c.assertTrue(DuelSessions.interact(b,stone),"B invited");DuelSessions.control(b,d.id,0);c.assertTrue(d.stage==DuelSessions.Stage.CONFIRMING&&d.acceptedB&&!d.acceptedA,"One consent cannot start");DuelSessions.control(a,d.id,0);c.assertTrue(d.stage==DuelSessions.Stage.COUNTDOWN,"Both consent before countdown");return d;}
 private void close(TestContext c,ServerPlayerEntity...players){for(var p:players)DuelSessions.leave(p,DuelSessions.Result.DISCONNECT);for(int n=0;n<22;n++){for(var d:DuelSessions.sessions(c.getWorld().getServer()))if(d.stage==DuelSessions.Stage.FINISHED)d.deadline=0;DuelSessions.tick(c.getWorld().getServer());}for(var p:players)p.discard();}
 @GameTest(templateName=ARENA,batchId="duel-registration",tickLimit=40)
 public void recipeStoneConsentReplayAndPvpDisabled(TestContext c){var pos=field(c);var a=player(c,pos,-2);var b=player(c,pos,2);var outsider=player(c,pos,4);var s=a.getServer();boolean pvp=s.isPvpEnabled();try{s.setPvpEnabled(false);c.assertTrue(!DuelSessions.interact(a,pos)&&DuelSessions.get(a)==null,"Safe refusal under real pvp=false flag");s.setPvpEnabled(true);
 var inputs=List.of(new ItemStack(Items.IRON_INGOT),new ItemStack(Items.IRON_INGOT),new ItemStack(Items.IRON_INGOT),new ItemStack(Items.STONE_BRICKS),new ItemStack(Items.SMOOTH_STONE),new ItemStack(Items.STONE_BRICKS),new ItemStack(Items.STONE_BRICKS),new ItemStack(Items.STONE_BRICKS),new ItemStack(Items.STONE_BRICKS));var input=CraftingRecipeInput.create(3,3,inputs);var match=c.getWorld().getRecipeManager().getFirstMatch(RecipeType.CRAFTING,input,c.getWorld()).orElseThrow();c.assertTrue(match.value().craft(input,c.getWorld().getRegistryManager()).isOf(DuelStone.BLOCK.asItem()),"Real survival recipe");
 c.assertTrue(!DuelStone.BLOCK.getDefaultState().getCollisionShape(c.getWorld(),pos).isEmpty(),"Volumetric collision");c.assertTrue(DuelSessions.interact(a,pos),"Waiting registration");var d=DuelSessions.get(a);DuelSessions.control(outsider,d.id,0);DuelSessions.control(a,UUID.randomUUID(),0);c.assertTrue(d.stage==DuelSessions.Stage.WAITING,"Forged confirmation cannot enroll/start");DuelSessions.interact(b,pos);DuelSessions.control(b,d.id,1);c.assertTrue(d.stage==DuelSessions.Stage.FINISHED&&d.result==DuelSessions.Result.DECLINED,"Invitation may be declined");c.assertTrue(!FistFights.busy(a)&&!FistFights.busy(b),"Declined invitation never enters restricted combat");close(c,a,b,outsider);
 }finally{s.setPvpEnabled(pvp);}c.complete();}
 @GameTest(templateName=ARENA,batchId="duel-live",tickLimit=240)
 public void symmetricCombatCounterDodgeKnockoutAndNoRealDeathOrRewards(TestContext c){var pos=field(c);var a=player(c,pos,-2);var b=player(c,pos,2);var d=confirm(c,pos,a,b);int xpA=a.totalExperience,xpB=b.totalExperience;
 DuelSessions.input(a,d.id,FistFightSession.Action.HEAVY);c.assertTrue(d.fight.player.action==FistFightSession.Action.IDLE,"Countdown rejects combat");
 c.runAtTick(65,()->{c.assertTrue(d.stage==DuelSessions.Stage.ACTIVE,"Server-owned countdown completed");a.refreshPositionAndAngles(pos.getX()+1.65,pos.getY(),pos.getZ()+.5,90,0);b.refreshPositionAndAngles(pos.getX()-.65,pos.getY(),pos.getZ()+.5,-90,0);DuelSessions.input(b,d.id,FistFightSession.Action.BLOCK);DuelSessions.input(a,d.id,FistFightSession.Action.QUICK);});
 c.runAtTick(71,()->{c.assertTrue(d.fight.opponent.health>95&&d.fight.opponent.health<100&&d.fight.opponent.counterTicks>0,"B timely guard blocks A and opens counter: stage="+d.stage+" hp="+d.fight.opponent.health+" guard="+d.fight.opponent.action+" guardTicks="+d.fight.opponent.actionTicks+" counter="+d.fight.opponent.counterTicks+" A="+d.fight.player.action+" ticks="+d.fight.player.actionTicks+" distance="+a.squaredDistanceTo(b)+" yaw="+a.getYaw()+","+b.getYaw()+" pos="+a.getPos()+","+b.getPos());DuelSessions.input(b,d.id,FistFightSession.Action.QUICK);});
 c.runAtTick(78,()->c.assertTrue(d.fight.player.health<100&&d.fight.player.action==FistFightSession.Action.STAGGER,"B uses same core counter against A"));
 c.runAtTick(100,()->{DuelSessions.input(b,d.id,FistFightSession.Action.DODGE);DuelSessions.input(a,d.id,FistFightSession.Action.QUICK);});
 c.runAtTick(107,()->{c.assertTrue(d.fight.opponent.health>95&&d.fight.opponent.stamina<100,"Dodge spends stamina and evades contact");DuelSessions.control(a,d.id,1);c.assertTrue(d.stage==DuelSessions.Stage.ACTIVE,"Forged decline cannot evade active surrender outcome");});
 c.runAtTick(140,()->{a.refreshPositionAndAngles(pos.getX()+1.65,pos.getY(),pos.getZ()+.5,90,0);b.refreshPositionAndAngles(pos.getX()-.65,pos.getY(),pos.getZ()+.5,-90,0);d.fight.opponent.health=1;DuelSessions.input(a,d.id,FistFightSession.Action.HEAVY);});
 c.runAtTick(157,()->{c.assertTrue(d.stage==DuelSessions.Stage.FINISHED&&d.result==DuelSessions.Result.KNOCKOUT&&a.getUuid().equals(d.winner),"Nonfatal knockout result");c.assertTrue(a.getHealth()==2&&b.getHealth()==2&&a.isAlive()&&b.isAlive(),"Even low real HP unchanged");c.assertTrue(a.getInventory().count(Items.DIAMOND)==3&&b.getInventory().count(Items.DIAMOND)==3&&WalletTransactions.balance(a.getInventory().getStack(8))==47&&WalletTransactions.balance(b.getInventory().getStack(8))==47&&a.totalExperience==xpA&&b.totalExperience==xpB,"No inventory drop, crown, XP or reward mutation");c.assertTrue(FistRewards.get(a.getServer()).pending(a.getUuid())==0&&FistRewards.get(a.getServer()).pending(b.getUuid())==0,"PvP never enters NPC payout ledger");});
 c.runAtTick(184,()->{c.assertTrue(DuelSessions.get(a)==null&&DuelSessions.get(b)==null,"Cleanup releases both");a.refreshPositionAndAngles(pos.getX(),pos.getY(),pos.getZ()-2,0,0);c.assertTrue(DuelSessions.interact(a,pos),"Immediate rematch on same stone");var fresh=DuelSessions.get(a);DuelSessions.input(a,d.id,FistFightSession.Action.HEAVY);DuelSessions.control(a,d.id,0);c.assertTrue(!fresh.id.equals(d.id)&&fresh.stage==DuelSessions.Stage.WAITING,"Old UUID cannot affect new round");close(c,a,b);c.complete();});
 }
 @GameTest(templateName=ARENA,batchId="duel-security",tickLimit=200)
 public void wallsFacingReachThirdPlayersAndWeaponCancellation(TestContext c){var pos=field(c);var a=player(c,pos,-2);var b=player(c,pos,2);var third=player(c,pos,5);var d=confirm(c,pos,a,b);
 c.runAtTick(65,()->{a.refreshPositionAndAngles(pos.getX()+1.65,pos.getY(),pos.getZ()+.5,90,0);b.refreshPositionAndAngles(pos.getX()-.65,pos.getY(),pos.getZ()+.5,-90,0);for(int z=-1;z<=1;z++)for(int y=1;y<=3;y++)c.getWorld().setBlockState(pos.add(0,y,z),Blocks.STONE.getDefaultState());DuelSessions.input(a,d.id,FistFightSession.Action.QUICK);a.damage(c.getWorld().getDamageSources().playerAttack(third),1);third.damage(c.getWorld().getDamageSources().playerAttack(a),1);c.assertTrue(a.getHealth()==2&&third.getHealth()==2,"Third-player interference blocked only for duelists");DuelSessions.input(third,d.id,FistFightSession.Action.HEAVY);});
 c.runAtTick(73,()->{c.assertTrue(d.fight.opponent.health==100&&d.fight.opponent.stamina==100,"No hit through stone wall, no outsider input");for(int z=-1;z<=1;z++)for(int y=1;y<=3;y++)c.getWorld().setBlockState(pos.add(0,y,z),Blocks.AIR.getDefaultState());a.setYaw(-90);DuelSessions.input(a,d.id,FistFightSession.Action.QUICK);});
 c.runAtTick(81,()->{c.assertTrue(d.fight.opponent.health==100,"Backward punch rejected");a.getInventory().setStack(0,new ItemStack(Items.IRON_SWORD));DuelSessions.input(a,d.id,FistFightSession.Action.HEAVY);a.damage(c.getWorld().getDamageSources().playerAttack(b),1);});
 c.runAtTick(84,()->{c.assertTrue(d.stage==DuelSessions.Stage.FINISHED&&d.result==DuelSessions.Result.INVALID&&b.getHealth()==2,"Weapon cancels without damage or item deletion");c.assertTrue(a.getMainHandStack().isOf(Items.IRON_SWORD),"Weapon retained");close(c,a,b,third);c.complete();});
 }
 @GameTest(templateName=ARENA,batchId="duel-independent",tickLimit=120)
 public void independentStonesOverlapTimeoutSurrenderAndBlockBreak(TestContext c){var pos=field(c);var second=pos.add(26,0,0);c.getWorld().setBlockState(second,DuelStone.BLOCK.getDefaultState());var a=player(c,pos,-2);var b=player(c,pos,2);var one=confirm(c,pos,a,b);var cc=player(c,second,-2);var dd=player(c,second,2);var two=confirm(c,second,cc,dd);c.assertTrue(one!=two&&!one.id.equals(two.id)&&!DuelSessions.interact(a,second),"Independent sessions and no duplicate player slot");var extra=player(c,pos.add(8,0,0),-2);var overlap=pos.add(8,0,0);c.getWorld().setBlockState(overlap,DuelStone.BLOCK.getDefaultState());c.assertTrue(!DuelSessions.interact(extra,overlap),"Overlapping arena rejected");
 c.runAtTick(65,()->{DuelSessions.control(b,one.id,2);c.assertTrue(one.stage==DuelSessions.Stage.FINISHED&&a.getUuid().equals(one.winner)&&two.stage==DuelSessions.Stage.ACTIVE,"Surrender does not alter other arena");c.getWorld().breakBlock(second,false);});
 c.runAtTick(69,()->{c.assertTrue(two.stage==DuelSessions.Stage.FINISHED&&two.result==DuelSessions.Result.STONE_REMOVED,"Broken stone terminates session");close(c,a,b,cc,dd,extra);c.complete();});
 }
 @GameTest(templateName=ARENA,batchId="duel-boundary",tickLimit=200)
 public void boundaryGraceDimensionAndInviteExpiry(TestContext c){var pos=field(c);var a=player(c,pos,-2);var b=player(c,pos,2);var d=confirm(c,pos,a,b);
 c.runAtTick(65,()->a.refreshPositionAndAngles(pos.getX()+7,pos.getY(),pos.getZ()+.5,90,0));
 c.runAtTick(70,()->a.refreshPositionAndAngles(pos.getX()+13,pos.getY(),pos.getZ()+.5,90,0));
 c.runAtTick(80,()->c.assertTrue(d.stage==DuelSessions.Stage.ACTIVE&&d.outA>0,"Leaving arena grants return grace"));
 c.runAtTick(133,()->c.assertTrue(d.stage==DuelSessions.Stage.FINISHED&&d.result==DuelSessions.Result.BOUNDARY&&b.getUuid().equals(d.winner),"Extended boundary exit forfeits"));
 c.runAtTick(160,()->{a.refreshPositionAndAngles(pos.getX(),pos.getY(),pos.getZ()-2,0,0);b.refreshPositionAndAngles(pos.getX(),pos.getY(),pos.getZ()+2,0,0);DuelSessions.interact(a,pos);var pending=DuelSessions.get(a);pending.deadline=0;DuelSessions.tick(a.getServer());c.assertTrue(pending.stage==DuelSessions.Stage.FINISHED&&pending.result==DuelSessions.Result.TIMEOUT,"Pending invite expiry bounded");close(c,a,b);c.complete();});
 }
 @GameTest(templateName=ARENA,batchId="duel-lifecycle",tickLimit=40)
 public void disconnectDimensionExternalDamageAndNpcExclusivity(TestContext c){var pos=field(c);var a=player(c,pos,-2);var b=player(c,pos,2);var d=confirm(c,pos,a,b);DuelSessions.leave(a,DuelSessions.Result.DISCONNECT);c.assertTrue(d.stage==DuelSessions.Stage.FINISHED&&b.getUuid().equals(d.winner),"Disconnect forfeits to remaining opponent");close(c,a,b);
  a=player(c,pos,-2);b=player(c,pos,2);d=confirm(c,pos,a,b);a.setServerWorld(a.getServer().getWorld(net.minecraft.world.World.NETHER));DuelSessions.tick(b.getServer());c.assertTrue(d.stage==DuelSessions.Stage.FINISHED&&d.result==DuelSessions.Result.DIMENSION,"Dimension change cancels");a.setServerWorld(c.getWorld());close(c,a,b);
  a=player(c,pos,-2);b=player(c,pos,2);d=confirm(c,pos,a,b);a.damage(c.getWorld().getDamageSources().outOfWorld(),.5f);c.assertTrue(d.stage==DuelSessions.Stage.FINISHED&&d.result==DuelSessions.Result.EXTERNAL_DAMAGE&&a.getHealth()<2&&a.getHealth()>0,"Environmental damage cancels then obeys ordinary world health: "+d.stage+"/"+d.result+" hp="+a.getHealth());close(c,a,b);
  a=player(c,pos,-2);b=player(c,pos,2);DuelSessions.interact(a,pos);var novice=FistRegistry.NOVICE.create(c.getWorld());novice.refreshPositionAndAngles(a.getX()+1,a.getY(),a.getZ(),0,0);c.getWorld().spawnEntity(novice);FistFights.invite(a,novice);c.assertTrue(!FistFights.confirm(a,novice),"Pending PvP excludes NPC enrollment");close(c,a,b);novice.discard();
  a=player(c,pos,-2);b=player(c,pos,2);protectedPlayer=a.getUuid();try{DuelSessions.interact(a,pos);d=DuelSessions.get(a);DuelSessions.interact(b,pos);DuelSessions.control(a,d.id,0);DuelSessions.control(b,d.id,0);c.assertTrue(d.stage==DuelSessions.Stage.FINISHED&&d.result==DuelSessions.Result.INVALID,"Protection adapter veto prevents start");}finally{protectedPlayer=null;}close(c,a,b);c.complete();
 }

}
